CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username VARCHAR(30) NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(80) NOT NULL, pixels JSONB NOT NULL, public BOOLEAN NOT NULL DEFAULT FALSE, plays INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_public_idx ON projects(updated_at DESC) WHERE public;

ALTER TABLE projects ADD COLUMN IF NOT EXISTS game JSONB;
